INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 27, 'theory', 'Quiz: fork, exec, mmap and ioctl');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 0, 'A parent started a child with fork, the child finished, and the parent keeps running and never calls wait. What does ps show?', '["Nothing: the kernel removes a finished process at once", "The child in state S, waiting for its parent", "The child in state Z marked defunct: a zombie", "Process number one has already adopted the child, and it is gone"]', 2, 'The record of a finished process is kept until the parent collects the status with wait. Adoption applies when the parent dies, but here it is alive; a zombie cannot be killed, the parent has to be fixed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 1, 'A child calls exit(300). What does WEXITSTATUS(status) return in the parent?', '["300", "44", "255", "0"]', 1, 'The parent gets only the low 8 bits of the exit code: 300 mod 256 is 44.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 2, 'In a pipeline a | b, process b reads from the pipe and does not finish after a has ended and exited. What is the most likely cause?', '["a became a zombie, so the pipe is not closed", "The 4096-byte pipe buffer is full", "b called exec and lost descriptor zero", "A write end of the pipe is still open somewhere, for example in the parent, so the reader never sees EOF"]', 3, 'EOF arrives only when every write end is closed. A forgotten copy in the parent or in another child keeps the pipe open. Zombies and the buffer size have no effect on this.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 3, 'A parent made an mmap with MAP_PRIVATE | MAP_ANONYMOUS, then forked, and the child wrote a number into the mapping. What does the parent see?', '["The old contents: the child''s write went to its own copy of the page", "The new number: mappings are always shared after fork", "SIGBUS on reading", "An EINVAL error on reading"]', 0, 'MAP_PRIVATE gives copy-on-write: after fork each process has its own copy of the modified page. Exchanging data needs MAP_SHARED.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 4, 'A request is defined as _IOW(''k'', 2, int). What does it mean, and what is its size in the request number?', '["The kernel writes an int to the user, size field 2", "No data, size field 0", "The user passes an int to the kernel, size field 4 (on a common platform)", "Data goes both ways, size field 8"]', 2, 'W means a write from the user''s side: the kernel reads the argument. The size comes from the type int, usually 4 bytes; the 2 is the command number, not the size.');
